const test = require("node:test");
const assert = require("node:assert");

const { Cache } = require("./cache");

test("capacity evicts least recently used", () => {
  const c = new Cache(2, 1000);
  c.put("a", 1, 0);
  c.put("b", 2, 1);
  c.get("a", 2);
  c.put("c", 3, 3);
  assert.strictEqual(c.get("a", 4), 1);
  assert.strictEqual(c.get("b", 4), undefined);
  assert.strictEqual(c.get("c", 4), 3);
});

test("get refreshes recency", () => {
  const c = new Cache(2, 1000);
  c.put("a", 1, 0);
  c.put("b", 2, 1);
  c.get("a", 2);
  c.get("b", 3);
  c.put("c", 3, 4);
  assert.strictEqual(c.get("a", 5), undefined);
  assert.strictEqual(c.get("b", 5), 2);
});

test("ttl expiry independent of capacity", () => {
  const c = new Cache(5, 10);
  c.put("a", 1, 0);
  assert.strictEqual(c.get("a", 9), 1);
  assert.strictEqual(c.get("a", 10), undefined);
  assert.strictEqual(c.get("a", 20), undefined);
});

