class Cache {
  constructor(capacity, ttl) {
    this.capacity = capacity;
    this.ttl = ttl;
    this.store = new Map(); // key -> [value, storedAt]
  }

  put(key, value, now) {
    if (this.store.has(key)) {
      this.store.delete(key);
    } else if (this.store.size >= this.capacity) {
      const oldestKey = this.store.keys().next().value;
      this.store.delete(oldestKey);
    }
    this.store.set(key, [value, now]);
  }

  get(key, now) {
    if (!this.store.has(key)) {
      return undefined;
    }
    const [value, storedAt] = this.store.get(key);
    if (now - storedAt >= this.ttl) {
      this.store.delete(key);
      return undefined;
    }
    this.store.delete(key);
    this.store.set(key, [value, storedAt]);
    return value;
  }
}

module.exports = { Cache };

